1. /**
2.  * Try lookup + creation helpers. A Try is an employee's honor-system
3.  * self-declaration that they tried a poutine — see ARCHITECTURE.md's data model.
4.  * Phase 2 added the read-only lookups below; Phase 3 adds `getTryForEmployee` +
5.  * `createTry` so the SubmissionDetail view can let an employee log a Try.
6.  */
7. import { createRow, listRows, type DataverseRow } from '../lib/dataverseClient';
8. import { ENTITY_SETS } from './constants';
9. 
10. export interface TryRow {
11.   rpo_tryid: string;
12.   poutineSubmissionId: string | null;
13.   employeeId: string | null;
14.   employeeName: string | null;
15.   triedOn: string | null;
16. }
17. 
18. const TRY_SELECT = ['rpo_tryid', 'rpo_poutinesubmissionid', 'rpo_employeeid', 'rpo_triedon'];
19. 
20. function escapeODataString(value: string): string {
21.   return value.replace(/'/g, "''");
22. }
23. 
24. function toTryRow(row: DataverseRow): TryRow {
25.   return {
26.     rpo_tryid: String(row.rpo_tryid),
27.     poutineSubmissionId: (row._rpo_poutinesubmissionid_value as string | null | undefined) ?? null,
28.     employeeId: (row._rpo_employeeid_value as string | null | undefined) ?? null,
29.     employeeName:
30.       (row['_rpo_employeeid_value@OData.Community.Display.V1.FormattedValue'] as string | undefined) ?? null,
31.     triedOn: (row.rpo_triedon as string | null | undefined) ?? null,
32.   };
33. }
34. 
35. /**
36.  * List all Try rows pointing at any of the given PoutineSubmission ids.
37.  * Used to compute try counts for the Browse feed and to resolve the Try ids
38.  * needed to fetch the Reviews tied to a submission (Review only links to Try,
39.  * not directly to PoutineSubmission — see rpo_Review's schema).
40.  */
41. export async function listTriesForSubmissions(submissionIds: string[]): Promise<TryRow[]> {
42.   if (submissionIds.length === 0) return [];
43.   const filter = submissionIds
44.     .map((id) => `_rpo_poutinesubmissionid_value eq '${escapeODataString(id)}'`)
45.     .join(' or ');
46.   const rows = await listRows(ENTITY_SETS.tries, {
47.     select: TRY_SELECT,
48.     filter,
49.     orderBy: ['rpo_triedon desc'],
50.   });
51.   return rows.map(toTryRow);
52. }
53. 
54. /**
55.  * Finds the given employee's existing Try for a submission, if any.
56.  *
57.  * See memory-bank.md's Phase 3 "one Try per employee per submission" decision:
58.  * the schema doesn't enforce this (no alternate key), but callers use this
59.  * check-then-create pattern (mirroring the submission-cap guard in
60.  * `src/data/submissions.ts`) to keep "logging a try" idempotent per employee,
61.  * so leaderboard/aggregate counts stay honest.
62.  */
63. export async function getTryForEmployee(submissionId: string, employeeId: string): Promise<TryRow | null> {
64.   const rows = await listRows(ENTITY_SETS.tries, {
65.     select: TRY_SELECT,
66.     filter:
67.       `_rpo_poutinesubmissionid_value eq '${escapeODataString(submissionId)}' ` +
68.       `and _rpo_employeeid_value eq '${escapeODataString(employeeId)}'`,
69.     top: 1,
70.   });
71.   return rows.length > 0 ? toTryRow(rows[0]) : null;
72. }
73. 
74. export interface CreateTryInput {
75.   submissionId: string;
76.   employeeId: string;
77. }
78. 
79. /**
80.  * Logs a Try for the given employee/submission. Callers should check
81.  * {@link getTryForEmployee} first and reuse the existing row instead of calling
82.  * this again — it is not re-checked here, following the same "caller enforces,
83.  * function stays a single atomic call" convention as
84.  * `src/data/submissions.ts#createSubmission`.
85.  */
86. export async function createTry(input: CreateTryInput): Promise<TryRow> {
87.   const triedOn = new Date().toISOString();
88.   const created = await createRow(ENTITY_SETS.tries, {
89.     'rpo_poutinesubmissionid@odata.bind': `/${ENTITY_SETS.poutineSubmissions}(${input.submissionId})`,
90.     'rpo_employeeid@odata.bind': `/${ENTITY_SETS.systemUsers}(${input.employeeId})`,
91.     rpo_triedon: triedOn,
92.   });
93.   return {
94.     rpo_tryid: String(created.rpo_tryid),
95.     poutineSubmissionId: input.submissionId,
96.     employeeId: input.employeeId,
97.     employeeName: null,
98.     triedOn,
99.   };
100. }
