4. interface StatusBadgeProps {
5.   status: SubmissionStatusValue;
6. }
7. 
8. const STATUS_MODIFIER: Record<SubmissionStatusValue, string> = {
9.   [SubmissionStatus.Draft]: 'draft',
10.   [SubmissionStatus.Submitted]: 'submitted',
11.   [SubmissionStatus.InReview]: 'in-review',
12.   [SubmissionStatus.Approved]: 'approved',
13.   [SubmissionStatus.Rejected]: 'rejected',
