1. import { useCallback, useEffect, useMemo, useState } from "react";
2. import { EmptyState } from "../components/EmptyState/EmptyState";
3. import { SubmissionForm, type SubmissionFormValues } from "../components/SubmissionForm/SubmissionForm";
4. import { MySubmissionsList } from "../components/MySubmissionsList/MySubmissionsList";
5. import { getCurrentUser } from "../data/currentUser";
6. import { getRestaurantById } from "../data/restaurants";
7. import { listTags, type TagRow } from "../data/tags";
8. import { SubmissionStatus, type SubmissionStatusValue } from "../data/constants";
9. import {
10.   MAX_ACTIVE_SUBMISSIONS,
11.   countActiveSubmissions,
12.   createSubmission,
13.   listMySubmissions,
14.   updateSubmission,
15.   withdrawSubmission,
16.   type PoutineSubmissionRow,
17. } from "../data/submissions";
18. import "./SubmitScreen.css";
19. 
20. type View = "new" | "mine" | "edit";
21. 
22. /** Draft-only, per the Phase 1 scope: only Draft submissions can be edited. */
23. const EDITABLE_STATUSES: SubmissionStatusValue[] = [SubmissionStatus.Draft];
24. 
25. export function SubmitScreen() {
26.   const [view, setView] = useState<View>("new");
27.   const [submitterId, setSubmitterId] = useState<string | null>(null);
28.   const [tags, setTags] = useState<TagRow[]>([]);
29.   const [submissions, setSubmissions] = useState<PoutineSubmissionRow[]>([]);
30.   const [activeCount, setActiveCount] = useState(0);
31.   const [editingSubmission, setEditingSubmission] = useState<PoutineSubmissionRow | null>(null);
32.   const [editingInitialValues, setEditingInitialValues] = useState<SubmissionFormValues | null>(null);
33.   const [isLoading, setIsLoading] = useState(true);
34.   const [loadError, setLoadError] = useState<string | null>(null);
35. 
36.   const refresh = useCallback(async (userId: string) => {
37.     const [mySubmissions, active] = await Promise.all([listMySubmissions(userId), countActiveSubmissions(userId)]);
38.     setSubmissions(mySubmissions);
39.     setActiveCount(active);
40.   }, []);
41. 
42.   useEffect(() => {
43.     let cancelled = false;
44.     async function load() {
45.       try {
46.         setIsLoading(true);
47.         const [user, tagRows] = await Promise.all([getCurrentUser(), listTags()]);
48.         if (cancelled) return;
49.         setSubmitterId(user.systemUserId);
50.         setTags(tagRows);
51.         await refresh(user.systemUserId);
52.       } catch (err) {
53.         if (!cancelled) setLoadError(err instanceof Error ? err.message : "Failed to load your submissions.");
54.       } finally {
55.         if (!cancelled) setIsLoading(false);
56.       }
57.     }
58.     load();
59.     return () => {
60.       cancelled = true;
61.     };
62.   }, [refresh]);
63. 
64.   const capReached = activeCount >= MAX_ACTIVE_SUBMISSIONS;
65. 
66.   async function handleCreate(values: SubmissionFormValues, status: SubmissionStatusValue) {
67.     if (!submitterId) throw new Error("Could not determine the current user.");
68.     // Re-check right before writing, in case the count changed since the form loaded.
69.     const currentActive = await countActiveSubmissions(submitterId);
70.     if (currentActive >= MAX_ACTIVE_SUBMISSIONS) {
71.       setActiveCount(currentActive);
72.       throw new Error(`You already have ${MAX_ACTIVE_SUBMISSIONS} active submissions. Withdraw a draft first.`);
73.     }
74.     await createSubmission({
75.       submitterId,
76.       existingRestaurantId: values.restaurant.existingRestaurantId,
77.       newRestaurantName: values.restaurant.existingRestaurantId ? undefined : values.restaurant.name,
78.       newRestaurantAddress: values.restaurant.existingRestaurantId ? undefined : values.restaurant.address,
79.       name: values.name,
80.       description: values.description,
81.       price: values.price,
82.       status: status as typeof SubmissionStatus.Draft | typeof SubmissionStatus.Submitted,
83.       tagIds: values.tagIds,
84.       photo: values.photo,
85.     });
86.     await refresh(submitterId);
87.   }
88. 
89.   async function handleEditSelect(submission: PoutineSubmissionRow) {
90.     setEditingSubmission(submission);
91.     setEditingInitialValues(null);
92.     setView("edit");
93.     const restaurant = submission.restaurantId ? await getRestaurantById(submission.restaurantId) : null;
94.     setEditingInitialValues({
95.       restaurant: restaurant
96.         ? { existingRestaurantId: restaurant.rpo_restaurantid, name: restaurant.rpo_name, address: restaurant.rpo_address ?? "" }
97.         : { name: "", address: "" },
98.       name: submission.rpo_name,
99.       description: submission.rpo_description ?? "",
100.       price: submission.rpo_price,
101.       tagIds: submission.tags.map((t) => t.rpo_tagid),
102.     });
103.   }
104. 
105.   async function handleUpdate(values: SubmissionFormValues, status: SubmissionStatusValue) {
106.     if (!editingSubmission || !submitterId) return;
107.     await updateSubmission(editingSubmission.rpo_poutinesubmissionid, {
108.       name: values.name,
109.       description: values.description,
110.       price: values.price,
111.       status,
112.       existingRestaurantId: values.restaurant.existingRestaurantId,
113.       newRestaurantName: values.restaurant.existingRestaurantId ? undefined : values.restaurant.name,
114.       newRestaurantAddress: values.restaurant.existingRestaurantId ? undefined : values.restaurant.address,
115.       tagIds: values.tagIds,
116.       photo: values.photo,
117.     });
118.     setEditingSubmission(null);
119.     setEditingInitialValues(null);
120.     setView("mine");
121.     await refresh(submitterId);
122.   }
123. 
124.   async function handleWithdraw(submission: PoutineSubmissionRow) {
125.     if (!submitterId) return;
126.     await withdrawSubmission(submission.rpo_poutinesubmissionid);
127.     await refresh(submitterId);
128.   }
129. 
130.   const capMessage = useMemo(
131.     () => `${activeCount} of ${MAX_ACTIVE_SUBMISSIONS} active submissions used`,
132.     [activeCount],
133.   );
134. 
135.   if (isLoading) {
136.     return <EmptyState title="Submit a poutine" description="Loading your submissions…" />;
137.   }
138. 
139.   if (loadError) {
140.     return <EmptyState title="Submit a poutine" description={loadError} />;
141.   }
142. 
143.   return (
144.     <div className="submit-screen">
145.       <header className="submit-screen__header">
146.         <p className="submit-screen__eyebrow">Phase 1</p>
147.         <h1 className="submit-screen__title">Submit a poutine</h1>
148.         <p className="submit-screen__cap">{capMessage}</p>
149.       </header>
150. 
151.       <nav className="submit-screen__tabs" aria-label="Submission views">
152.         <button
153.           type="button"
154.           className={`submit-screen__tab${view === "new" ? " submit-screen__tab--active" : ""}`}
155.           onClick={() => setView("new")}
156.         >
157.           New submission
158.         </button>
159.         <button
160.           type="button"
161.           className={`submit-screen__tab${view === "mine" ? " submit-screen__tab--active" : ""}`}
162.           onClick={() => setView("mine")}
163.         >
164.           My submissions ({submissions.length})
165.         </button>
166.       </nav>
167. 
168.       {view === "new" && <SubmissionForm tags={tags} onSave={handleCreate} capReached={capReached} />}
169. 
170.       {view === "mine" && (
171.         <MySubmissionsList submissions={submissions} onEdit={handleEditSelect} onWithdraw={handleWithdraw} />
172.       )}
173. 
174.       {view === "edit" &&
175.         editingSubmission &&
176.         (editingInitialValues ? (
177.           <SubmissionForm
178.             tags={tags}
179.             initialValues={editingInitialValues}
180.             allowedStatuses={EDITABLE_STATUSES}
181.             onSave={handleUpdate}
182.             onCancel={() => {
183.               setEditingSubmission(null);
184.               setEditingInitialValues(null);
185.               setView("mine");
186.             }}
187.           />
188.         ) : (
189.           <EmptyState title="Loading" description="Loading this submission…" />
190.         ))}
191.     </div>
192.   );
193. }
