1. /**
2.  * PoutineSubmission CRUD, the 5-active-submission cap, and Tag association logic
3.  * for the "Submit a poutine" experience (Phase 1).
4.  */
5. import {
6.   associateRows,
7.   createRow,
8.   deleteRow,
9.   disassociateRows,
10.   getRow,
11.   listRows,
12.   updateRow,
13.   uploadFileImage,
14.   type DataverseRow,
15. } from '../lib/dataverseClient';
16. import { createRestaurant } from './restaurants';
17. import {
18.   ACTIVE_SUBMISSION_STATUSES,
19.   ENTITY_SETS,
20.   MAX_ACTIVE_SUBMISSIONS,
21.   SUBMISSION_TAG_RELATIONSHIP,
22.   SubmissionStatus,
23.   type SubmissionStatusValue,
24. } from './constants';
25. import type { TagRow } from './tags';
26. 
27. export interface PoutineSubmissionRow {
28.   rpo_poutinesubmissionid: string;
29.   rpo_name: string;
30.   rpo_description: string | null;
31.   rpo_price: number | null;
32.   rpo_status: SubmissionStatusValue;
33.   restaurantId: string | null;
34.   restaurantName: string | null;
35.   createdOn: string | null;
36.   tags: TagRow[];
37.   /** Data-URL of the thumbnail-sized photo, when `rpo_photo` was selected and one exists. */
38.   photoDataUrl: string | null;
39. }
40. 
41. const SUBMISSION_SELECT = ['rpo_poutinesubmissionid', 'rpo_name', 'rpo_description', 'rpo_price', 'rpo_status', 'rpo_restaurantid', 'createdon'];
42. /**
43.  * Same as {@link SUBMISSION_SELECT} plus the `rpo_photo` image column. Dataverse
44.  * returns image columns as a base64-encoded thumbnail directly alongside other
45.  * selected fields on a normal retrieve (no separate download call needed) — see
46.  * "Use image column data in Microsoft Dataverse" in the Dataverse docs. Kept as a
47.  * separate select list so Phase 1's My Submissions view (which doesn't render a
48.  * photo) isn't forced to pay for the extra payload.
49.  */
50. const SUBMISSION_SELECT_WITH_PHOTO = [...SUBMISSION_SELECT, 'rpo_photo'];
51. const TAG_EXPAND = `${SUBMISSION_TAG_RELATIONSHIP}($select=rpo_tagid,rpo_name)`;
52. 
53. function escapeODataString(value: string): string {
54.   return value.replace(/'/g, "''");
55. }
56. 
57. function toSubmissionRow(row: DataverseRow): PoutineSubmissionRow {
58.   const restaurantName = row['_rpo_restaurantid_value@OData.Community.Display.V1.FormattedValue'] as
59.     | string
60.     | undefined;
61.   const relatedTags = (row[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
62.   const photo = row.rpo_photo as string | null | undefined;
63.   return {
64.     rpo_poutinesubmissionid: String(row.rpo_poutinesubmissionid),
65.     rpo_name: (row.rpo_name as string | undefined) ?? '',
66.     rpo_description: (row.rpo_description as string | null | undefined) ?? null,
67.     rpo_price: (row.rpo_price as number | null | undefined) ?? null,
68.     rpo_status: (row.rpo_status as SubmissionStatusValue | undefined) ?? SubmissionStatus.Draft,
69.     restaurantId: (row._rpo_restaurantid_value as string | null | undefined) ?? null,
70.     restaurantName: restaurantName ?? null,
71.     createdOn: (row.createdon as string | null | undefined) ?? null,
72.     tags: relatedTags.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' })),
73.     photoDataUrl: photo ? `data:image;base64,${photo}` : null,
74.   };
75. }
76. 
77. /** List all submissions created by the given SystemUser, newest first, including their tags. */
78. export async function listMySubmissions(submitterId: string): Promise<PoutineSubmissionRow[]> {
79.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
80.     select: SUBMISSION_SELECT,
81.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}'`,
82.     orderBy: ['createdon desc'],
83.     expand: TAG_EXPAND,
84.   });
85.   return rows.map(toSubmissionRow);
86. }
87. 
88. /**
89.  * List every submission visible in the public Browse feed — i.e. those that have
90.  * cleared moderation. Only `Approved` is a publicly-visible status: Draft/Submitted/
91.  * In Review are still going through the submitter's or moderator's workflow, and
92.  * Rejected never becomes public. Includes tags and the photo thumbnail (if any).
93.  */
94. export async function listApprovedSubmissions(): Promise<PoutineSubmissionRow[]> {
95.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
96.     select: SUBMISSION_SELECT_WITH_PHOTO,
97.     filter: `rpo_status eq ${SubmissionStatus.Approved}`,
98.     orderBy: ['createdon desc'],
99.     expand: TAG_EXPAND,
100.   });
101.   return rows.map(toSubmissionRow);
102. }
103. 
104. /** Count how many of the submitter's submissions are in an "active" (cap-counting) status. */
105. export async function countActiveSubmissions(submitterId: string): Promise<number> {
106.   const statusFilter = ACTIVE_SUBMISSION_STATUSES.map((s) => `rpo_status eq ${s}`).join(' or ');
107.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
108.     select: ['rpo_poutinesubmissionid'],
109.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}' and (${statusFilter})`,
110.   });
111.   return rows.length;
112. }
113. 
114. export interface CreateSubmissionInput {
115.   submitterId: string;
116.   /** GUID of an existing restaurant, when the employee picked one from search results. */
117.   existingRestaurantId?: string;
118.   /** Required when existingRestaurantId is not provided. */
119.   newRestaurantName?: string;
120.   newRestaurantAddress?: string;
121.   name: string;
122.   description: string;
123.   price: number | null;
124.   status: typeof SubmissionStatus.Draft | typeof SubmissionStatus.Submitted;
125.   tagIds: string[];
126.   photo?: File;
127. }
128. 
129. /**
130.  * Creates a PoutineSubmission (creating its Restaurant first if a new one was entered),
131.  * associates the selected tags, and uploads the photo if one was provided.
132.  *
133.  * Callers must enforce the active-submission cap (via {@link countActiveSubmissions})
134.  * before calling this — it is not re-checked here to keep this function a single
135.  * atomic sequence of Dataverse calls.
136.  */
137. export async function createSubmission(input: CreateSubmissionInput): Promise<PoutineSubmissionRow> {
138.   let restaurantId = input.existingRestaurantId;
139.   if (!restaurantId) {
140.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
141.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
142.     }
143.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
144.     restaurantId = restaurant.rpo_restaurantid;
145.   }
146. 
147.   const created = await createRow(ENTITY_SETS.poutineSubmissions, {
148.     rpo_name: input.name.trim(),
149.     rpo_description: input.description.trim() || null,
150.     rpo_price: input.price,
151.     rpo_status: input.status,
152.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
153.     'rpo_submitterid@odata.bind': `/${ENTITY_SETS.systemUsers}(${input.submitterId})`,
154.   });
155.   const submissionId = String(created.rpo_poutinesubmissionid);
156. 
157.   for (const tagId of input.tagIds) {
158.     await associateRows(
159.       ENTITY_SETS.poutineSubmissions,
160.       submissionId,
161.       SUBMISSION_TAG_RELATIONSHIP,
162.       ENTITY_SETS.tags,
163.       tagId,
164.     );
165.   }
166. 
167.   if (input.photo) {
168.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
169.   }
170. 
171.   return getSubmission(submissionId);
172. }
173. 
174. /** Fetch a single submission (with its tags) by id. */
175. export async function getSubmission(submissionId: string): Promise<PoutineSubmissionRow> {
176.   const row = await getRow(ENTITY_SETS.poutineSubmissions, submissionId, [...SUBMISSION_SELECT]);
177.   // GetItem doesn't accept $expand in this connector op the way List does for our purposes here,
178.   // so tags are fetched separately and merged in.
179.   const tags = await getSubmissionTags(submissionId);
180.   return { ...toSubmissionRow(row), tags };
181. }
182. 
183. /** Same as {@link getSubmission}, but also includes the `rpo_photo` thumbnail — used by the Browse detail view. */
184. export async function getSubmissionWithPhoto(submissionId: string): Promise<PoutineSubmissionRow> {
185.   const row = await getRow(ENTITY_SETS.poutineSubmissions, submissionId, [...SUBMISSION_SELECT_WITH_PHOTO]);
186.   const tags = await getSubmissionTags(submissionId);
187.   return { ...toSubmissionRow(row), tags };
188. }
189. 
190. /** Fetch the tags currently associated with a submission. */
191. export async function getSubmissionTags(submissionId: string): Promise<TagRow[]> {
192.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
193.     select: ['rpo_poutinesubmissionid'],
194.     filter: `rpo_poutinesubmissionid eq '${escapeODataString(submissionId)}'`,
195.     expand: TAG_EXPAND,
196.     top: 1,
197.   });
198.   const related = (rows[0]?.[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
199.   return related.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' }));
200. }
201. 
202. export interface UpdateSubmissionInput {
203.   name: string;
204.   description: string;
205.   price: number | null;
206.   status: SubmissionStatusValue;
207.   existingRestaurantId?: string;
208.   newRestaurantName?: string;
209.   newRestaurantAddress?: string;
210.   tagIds: string[];
211.   photo?: File;
212. }
213. 
214. /** Updates a Draft submission's fields, restaurant, tags (diffed), and optionally its photo. */
215. export async function updateSubmission(submissionId: string, input: UpdateSubmissionInput): Promise<PoutineSubmissionRow> {
216.   let restaurantId = input.existingRestaurantId;
217.   if (!restaurantId) {
218.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
219.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
220.     }
221.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
222.     restaurantId = restaurant.rpo_restaurantid;
223.   }
224. 
225.   await updateRow(ENTITY_SETS.poutineSubmissions, submissionId, {
226.     rpo_name: input.name.trim(),
227.     rpo_description: input.description.trim() || null,
228.     rpo_price: input.price,
229.     rpo_status: input.status,
230.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
231.   });
232. 
233.   const currentTags = await getSubmissionTags(submissionId);
234.   const currentTagIds = new Set(currentTags.map((t) => t.rpo_tagid));
235.   const nextTagIds = new Set(input.tagIds);
236. 
237.   for (const tagId of nextTagIds) {
238.     if (!currentTagIds.has(tagId)) {
239.       await associateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
240.     }
241.   }
242.   for (const tagId of currentTagIds) {
243.     if (!nextTagIds.has(tagId)) {
244.       await disassociateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
245.     }
246.   }
247. 
248.   if (input.photo) {
249.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
250.   }
251. 
252.   return getSubmission(submissionId);
253. }
254. 
255. /** Hard-deletes a submission. UI restricts this action to the employee's own Draft submissions. */
256. export async function withdrawSubmission(submissionId: string): Promise<void> {
257.   await deleteRow(ENTITY_SETS.poutineSubmissions, submissionId);
258. }
