35.   const [loadError, setLoadError] = useState<string | null>(null);
36. 
37.   useEffect(() => {
38.     let cancelled = false;
39.     async function load() {
40.       try {
41.         setIsLoadingShell(true);
42.         const [seasonRows, categoryRows, hallOfFameRows] = await Promise.all([
43.           listSeasons(),
44.           listCategories(),
45.           listHallOfFameEntries(),
46.         ]);
47.         if (cancelled) return;
48.         setSeasons(seasonRows);
49.         setCategories(categoryRows);
50.         setHallOfFame(hallOfFameRows);
51.         setSelectedSeasonId(pickDefaultSeason(seasonRows)?.rpo_seasonid ?? null);
52.         setSelectedCategoryId(categoryRows[0]?.rpo_categoryid ?? null);
53.       } catch (err) {
54.         if (!cancelled) setLoadError(err instanceof Error ? err.message : "Failed to load leaderboards.");
55.       } finally {
56.         if (!cancelled) setIsLoadingShell(false);
57.       }
