1. /**
2.  * Read-only Leaderboards + Hall of Fame data access (Phase 5).
3.  *
4.  * Season, Category, Season Result, Season Result Entry, and Hall of Fame Entry
5.  * are all populated server-side by the nightly leaderboard computation flow
6.  * and the season rollover flow (see ARCHITECTURE.md §4 and its data model
7.  * §1) — including the AI-assisted "Best Critic" review-helpfulness score,
8.  * which only that backend flow can compute (via the Review Quality agent).
9.  * This module never writes to these tables and never re-derives scores
10.  * client-side; it only reads the already-computed snapshot.
11.  *
12.  * See memory-bank.md's Phase 5 "v1 scope decision" for why the *current*
13.  * season's standings are also read from the persisted `SeasonResultEntry`
14.  * snapshot here, rather than live-recomputed on demand as ARCHITECTURE.md's
15.  * "on-demand" note describes — flagged there for human revisit.
16.  */
17. import { listRows, type DataverseRow } from '../lib/dataverseClient';
18. import { ENTITY_SETS, SeasonStatus, type SeasonStatusValue } from './constants';
19. 
20. function escapeODataString(value: string): string {
21.   return value.replace(/'/g, "''");
22. }
23. 
24. function formattedValue(row: DataverseRow, lookupField: string): string | null {
25.   return (row[`${lookupField}@OData.Community.Display.V1.FormattedValue`] as string | undefined) ?? null;
26. }
27. 
28. export interface SeasonRow {
29.   rpo_seasonid: string;
30.   rpo_name: string;
31.   startDate: string | null;
32.   endDate: string | null;
33.   status: SeasonStatusValue;
34. }
35. 
36. const SEASON_SELECT = ['rpo_seasonid', 'rpo_name', 'rpo_startdate', 'rpo_enddate', 'rpo_status'];
37. 
38. function toSeasonRow(row: DataverseRow): SeasonRow {
39.   return {
40.     rpo_seasonid: String(row.rpo_seasonid),
41.     rpo_name: (row.rpo_name as string | undefined) ?? '',
42.     startDate: (row.rpo_startdate as string | null | undefined) ?? null,
43.     endDate: (row.rpo_enddate as string | null | undefined) ?? null,
44.     status: (row.rpo_status as SeasonStatusValue | undefined) ?? SeasonStatus.Closed,
45.   };
46. }
47. 
48. /** All seasons, most recently started first. */
49. export async function listSeasons(): Promise<SeasonRow[]> {
50.   const rows = await listRows(ENTITY_SETS.seasons, {
51.     select: SEASON_SELECT,
52.     orderBy: ['rpo_startdate desc'],
53.   });
54.   return rows.map(toSeasonRow);
55. }
56. 
57. /**
58.  * The season the Leaderboards screen defaults to: the `Active` season if one
59.  * exists, otherwise the most recently started season (e.g. briefly between a
60.  * season close and the next season opening).
61.  */
62. export function pickDefaultSeason(seasons: SeasonRow[]): SeasonRow | null {
63.   return seasons.find((s) => s.status === SeasonStatus.Active) ?? seasons[0] ?? null;
64. }
65. 
66. export interface CategoryRow {
67.   rpo_categoryid: string;
68.   rpo_name: string;
69.   description: string | null;
70.   computationType: string | null;
71. }
72. 
73. const CATEGORY_SELECT = ['rpo_categoryid', 'rpo_name', 'rpo_description', 'rpo_computationtype'];
74. 
75. function toCategoryRow(row: DataverseRow): CategoryRow {
76.   return {
77.     rpo_categoryid: String(row.rpo_categoryid),
78.     rpo_name: (row.rpo_name as string | undefined) ?? '',
79.     description: (row.rpo_description as string | null | undefined) ?? null,
80.     computationType: (row.rpo_computationtype as string | null | undefined) ?? null,
81.   };
82. }
83. 
84. /**
85.  * Display order for the four launch categories (PRODUCT.md §Capabilities and
86.  * Constraints). See memory-bank.md's Phase 5 v1 scope decision. Any category
87.  * introduced later that isn't in this list is appended after these four,
88.  * alphabetically, rather than being hidden.
89.  */
90. export const LEADERBOARD_CATEGORY_ORDER = ['Best Seller', 'Top Poutine', 'Best Supporter', 'Best Critic'];
91. 
92. /** All Categories, ordered per {@link LEADERBOARD_CATEGORY_ORDER}. */
93. export async function listCategories(): Promise<CategoryRow[]> {
94.   const rows = await listRows(ENTITY_SETS.categories, { select: CATEGORY_SELECT });
95.   const categories = rows.map(toCategoryRow);
96.   return categories.sort((a, b) => {
97.     const indexA = LEADERBOARD_CATEGORY_ORDER.indexOf(a.rpo_name);
98.     const indexB = LEADERBOARD_CATEGORY_ORDER.indexOf(b.rpo_name);
99.     if (indexA === -1 && indexB === -1) return a.rpo_name.localeCompare(b.rpo_name);
100.     if (indexA === -1) return 1;
101.     if (indexB === -1) return -1;
102.     return indexA - indexB;
103.   });
104. }
105. 
106. export interface SeasonResultEntryRow {
107.   rpo_seasonresultentryid: string;
108.   rank: number;
109.   score: number | null;
110.   employeeId: string | null;
111.   employeeName: string | null;
112.   poutineSubmissionId: string | null;
113.   poutineSubmissionName: string | null;
114. }
115. 
116. /**
117.  * The ranked entries for a season/category, already sorted by rank. Returns
118.  * an empty array — never an error — when the nightly flow hasn't computed a
119.  * `SeasonResult` for this season/category yet, so callers render an empty
120.  * state instead of crashing.
121.  */
122. export async function listSeasonResultEntries(seasonId: string, categoryId: string): Promise<SeasonResultEntryRow[]> {
123.   const seasonResults = await listRows(ENTITY_SETS.seasonResults, {
124.     select: ['rpo_seasonresultid'],
125.     filter:
126.       `_rpo_seasonid_value eq '${escapeODataString(seasonId)}' ` +
127.       `and _rpo_categoryid_value eq '${escapeODataString(categoryId)}'`,
128.     top: 1,
129.   });
130.   const seasonResult = seasonResults[0];
131.   if (!seasonResult) return [];
132. 
133.   const entryRows = await listRows(ENTITY_SETS.seasonResultEntries, {
134.     select: ['rpo_seasonresultentryid', 'rpo_rank', 'rpo_score', 'rpo_employeeid', 'rpo_poutinesubmissionid'],
135.     filter: `_rpo_seasonresultid_value eq '${escapeODataString(String(seasonResult.rpo_seasonresultid))}'`,
136.     orderBy: ['rpo_rank asc'],
137.   });
138. 
139.   return entryRows.map((row) => ({
140.     rpo_seasonresultentryid: String(row.rpo_seasonresultentryid),
141.     rank: Number(row.rpo_rank ?? 0),
142.     score: (row.rpo_score as number | null | undefined) ?? null,
143.     employeeId: (row._rpo_employeeid_value as string | null | undefined) ?? null,
144.     employeeName: formattedValue(row, '_rpo_employeeid_value'),
145.     poutineSubmissionId: (row._rpo_poutinesubmissionid_value as string | null | undefined) ?? null,
146.     poutineSubmissionName: formattedValue(row, '_rpo_poutinesubmissionid_value'),
147.   }));
148. }
149. 
150. export interface HallOfFameEntryRow {
151.   rpo_halloffameentryid: string;
152.   seasonId: string | null;
153.   seasonName: string | null;
154.   categoryId: string | null;
155.   categoryName: string | null;
156.   employeeId: string | null;
157.   employeeName: string | null;
158.   poutineSubmissionId: string | null;
159.   poutineSubmissionName: string | null;
160.   badgeTitle: string | null;
161. }
162. 
163. /** All-time Hall of Fame entries, most recently archived first. */
164. export async function listHallOfFameEntries(): Promise<HallOfFameEntryRow[]> {
165.   const rows = await listRows(ENTITY_SETS.hallOfFameEntries, {
166.     select: [
167.       'rpo_halloffameentryid',
168.       'rpo_badgetitle',
169.       'rpo_seasonid',
170.       'rpo_categoryid',
171.       'rpo_employeeid',
172.       'rpo_poutinesubmissionid',
173.     ],
174.     orderBy: ['createdon desc'],
175.   });
176.   return rows.map((row) => ({
177.     rpo_halloffameentryid: String(row.rpo_halloffameentryid),
178.     seasonId: (row._rpo_seasonid_value as string | null | undefined) ?? null,
179.     seasonName: formattedValue(row, '_rpo_seasonid_value'),
180.     categoryId: (row._rpo_categoryid_value as string | null | undefined) ?? null,
181.     categoryName: formattedValue(row, '_rpo_categoryid_value'),
182.     employeeId: (row._rpo_employeeid_value as string | null | undefined) ?? null,
183.     employeeName: formattedValue(row, '_rpo_employeeid_value'),
184.     poutineSubmissionId: (row._rpo_poutinesubmissionid_value as string | null | undefined) ?? null,
185.     poutineSubmissionName: formattedValue(row, '_rpo_poutinesubmissionid_value'),
186.     badgeTitle: (row.rpo_badgetitle as string | null | undefined) ?? null,
187.   }));
